namespace CLRS.LeetCode;

// problem #2090: K Radius Subarray Averages
public partial class Solution
{
    public int[] GetAverages(int[] nums, int k)
    {
        int[] prefix = new int[nums.Length];
        prefix[0] = nums[0];
        for (int i = 1; i < nums.Length; ++i)
        {
            prefix[i] = prefix[i - 1] + nums[i];
        }

        int[] result = new int[nums.Length];
        for (int i = 0; i < nums.Length; ++i)
        {
            if (i < k || i + k >= nums.Length)
            {
                result[i] = -1;
            }
            else
            {
                var calcResult1 = prefix[i + k] - prefix[i] + nums[i];
                var calcResult2 = prefix[i] - prefix[i - k] + nums[i - k];
                result[i] = (calcResult1 + calcResult2 - nums[i]) / (2 * k + 1);
            }
        }

        // Input: nums = [7,4,3,9,1,8,5,2,6], k = 3
        // prefix = [7, 11, 14, 23, 24, 32, 37, 39, 45]
        return result;
    }
}

